"use strict";(self.webpackChunkenablemodel=self.webpackChunkenablemodel||[]).push([[4348],{4602:(e,s,t)=>{t.r(s),t.d(s,{assets:()=>d,contentTitle:()=>o,default:()=>h,frontMatter:()=>r,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"forces-that-disable/abandonment","title":"Abandonment","description":"When care is withdrawn -- and access fades away.","source":"@site/docs/forces-that-disable/abandonment.md","sourceDirName":"forces-that-disable","slug":"/forces-that-disable/abandonment","permalink":"/docs/forces-that-disable/abandonment","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Abandonment"},"sidebar":"tutorialSidebar","previous":{"title":"Forces that Disable","permalink":"/docs/category/forces-that-disable"},"next":{"title":"Disability Dongles","permalink":"/docs/forces-that-disable/disability-dongles"}}');var n=t(4848),a=t(8453);const r={title:"Abandonment"},o=void 0,d={},l=[{value:"What It Is",id:"what-it-is",level:2},{value:"Why It Happens",id:"why-it-happens",level:2},{value:"Where It Happens (ENABLE Stages)",id:"where-it-happens-enable-stages",level:2},{value:"How It Disables",id:"how-it-disables",level:2},{value:"Why It Matters",id:"why-it-matters",level:2},{value:"Real-World Examples",id:"real-world-examples",level:2},{value:"What Care Sounds Like",id:"what-care-sounds-like",level:2},{value:"What Neglect Sounds Like",id:"what-neglect-sounds-like",level:2}];function c(e){const s={a:"a",admonition:"admonition",blockquote:"blockquote",br:"br",em:"em",h2:"h2",hr:"hr",li:"li",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(s.p,{children:"When care is withdrawn -- and access fades away."}),"\n",(0,n.jsx)(s.h2,{id:"what-it-is",children:"What It Is"}),"\n",(0,n.jsx)(s.p,{children:"Abandonment is a disabling force. It occurs when accessibility that once existed is withdrawn -- quietly or suddenly -- and leaves people crippled: a loss of functionality they previously relied on."}),"\n",(0,n.jsx)(s.p,{children:"Sometimes abandonment creeps in through drift: a missed test, a forgotten feature, a budget line quietly deleted. Other times, it arrives through decisive action: a redesign with no fallback, a system upgrade that breaks compatibility, or a shift in leadership that deprioritizes inclusion."}),"\n",(0,n.jsx)(s.p,{children:"Abandonment can be deliberate. It is sometimes framed as modernization, efficiency, or cost savings -- but behind the language of \u201ctradeoffs\u201d is often a calculated decision to cut disabled people loose. Cruelty doesn't always look like hostility. Sometimes it's a shrug."}),"\n",(0,n.jsx)(s.p,{children:"Abandonment doesn't always announce itself. It hides inside silence: a caption track that disappears without notice, a button that stops working with no fix, an earlier act of care allowed to expire. But quiet doesn't mean harmless -- or blameless."}),"\n",(0,n.jsxs)(s.p,{children:["Abandonment causes harm. It breaks trust, severs continuity, and undermines autonomy. When access fades and no one ",(0,n.jsx)(s.a,{href:"/docs/builder-side",children:"intervenes"}),", the result is structurally violent -- not because nothing was done, but because something people rely on becomes unavailable, potentially placing their bodies in harm's way."]}),"\n",(0,n.jsx)(s.p,{children:"Abandonment doesn't happen on its own. It's the outcome of decisions -- or the refusal to make them. When access that was once present disappears, the message is clear: accessibility was conditional. Inclusion was expendable."}),"\n",(0,n.jsxs)(s.admonition,{title:"A biosocial perspective",type:"tip",children:[(0,n.jsx)(s.p,{children:"Abandonment harms bodies, reshapes behavior and emotion, and results from decisions made by people, institutions, and culture. This page uses a biosocial lens to describe how loss of accessibility reverberates across all three."}),(0,n.jsx)(s.p,{children:"This page is a contribution to social medicine -- mapping how abandonment of digital accessibility constitutes structural harm, and how its drivers and effects extend beyond code into bodies, institutions, and systems of care."})]}),"\n",(0,n.jsx)(s.h2,{id:"why-it-happens",children:"Why It Happens"}),"\n",(0,n.jsxs)(s.p,{children:["Abandonment happens when accessibility is seen as optional, expensive, or forgettable. It follows shifts in power, priorities, and personnel -- but it's often rooted in something deeper: the belief that disabled people don't exist ",(0,n.jsx)(s.em,{children:"here"}),", or don't matter ",(0,n.jsx)(s.em,{children:"here"}),"."]}),"\n",(0,n.jsx)(s.p,{children:"Abandonment is propped up by bias, turnover, progress rhetoric, planned obsolescence, hostility, silence, instability, silence, ambiguity, and monopoly logic."}),"\n",(0,n.jsxs)(s.p,{children:["Bias drives abandonment. When teams say \u201cwe don't have disabled users,\u201d they aren't reporting a fact -- they're revealing who they imagined during ",(0,n.jsx)(s.a,{href:"/docs/builder-side/design",children:"design"}),". Abandonment takes hold when accessibility is seen as a burden instead of a baseline, a luxury instead of a right."]}),"\n",(0,n.jsx)(s.p,{children:"Turnover accelerates abandonment. The people who once fought for access may leave, retire, or pass away. Their replacements may not even know what was lost -- or why it mattered. When accessibility work is embodied in individuals but not embedded in systems, access can vanish with them. Over time, responsibility diffuses, institutional memory fades, and features quietly disappear."}),"\n",(0,n.jsx)(s.p,{children:"Modernization justifies abandonment. Leaders sometimes defend inaccessible upgrades by saying they had to \u201cmove fast\u201d or \u201cstreamline the experience.\u201d But what's framed as progress may actually erase prior inclusion."}),"\n",(0,n.jsx)(s.p,{children:"Planned obsolescence rationalizes abandonment. Yes, sometimes, abandonment is planned. Accessibility may be withdrawn not because it's broken, but because supporting it gets in the way of selling something new. A tool must stop working -- or stop meeting needs -- so another can replace it. In these cases, obsolescence is manufactured. Inclusion is treated as a blocker to product strategy. What's marketed as innovation is often exclusion in a newer wrapper."}),"\n",(0,n.jsx)(s.p,{children:"Hostility compels abandonment. In some cases, accessibility work is deliberately defunded, discredited, or dismantled. Accessibility may be reframed as political, stigmatized as wasteful, or suppressed outright. This isn't drift -- it's backlash. It's a politically motivated withdrawal of care; coercion resulting in cultural chill. It\u2019s the result of pressure campaigns, culture war rhetoric, or ideological mandates that compel institutions that support inclusion to retreat. Abandonment becomes a form of ideological compliance."}),"\n",(0,n.jsx)(s.p,{children:"Instability expedites abandonment. In some urgent situations, access disappears fast. Systems break under pressure -- not because emergencies make failure inevitable, but because care wasn\u2019t embedded to withstand it. What should have been resilient collapses. What should have been maintained is left to fend for itself. Under high stakes, the result is high-speed abandonment, often too late to fix. This loss transforms vital services into immediate barriers, with severe consequences, including increased hospitalization risk. When accessibility breaks in a crisis, the instability reveals that it was always going to break. It was never built to hold."}),"\n",(0,n.jsx)(s.p,{children:"Silence sustains abandonment. Abandonment rarely announces itself. It doesn't require cruelty -- just indifference, convenience, or an unwillingness to ask who's being left behind."}),"\n",(0,n.jsx)(s.p,{children:"Ambiguity protects abandonment. When responsibilities are vague, standards unenforced, or documentation incomplete, it becomes easier to pretend nothing broke -- or that no one is to blame. Ambiguity lets abandonment masquerade as oversight. It prevents users from knowing what to expect, prevents teams from knowing what to maintain, and prevents accountability when access disappears. In a fog of ambiguity, harm hides in plain sight -- and is carried out with plausible deniability."}),"\n",(0,n.jsx)(s.p,{children:'Monopoly logic emboldens abandonment. When an organization is the only one in its domain working on accessibility, they can misread their exclusivity as insulation rather than responsibility. Because so few actors across industries take on accessibility work, solitude is common, and may get treated as security. Leaders may say "no one else is doing this," with the belief that they can pause the work without losing ground, that no one will outpace them, claim the space, publish first, or build a competing solution. Exclusivity makes abandonment feel low-risk. But when the sole steward steps away, they desert people who cannot pause their lives.'}),"\n",(0,n.jsx)(s.h2,{id:"where-it-happens-enable-stages",children:"Where It Happens (ENABLE Stages)"}),"\n",(0,n.jsxs)(s.table,{children:[(0,n.jsx)(s.thead,{children:(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.th,{children:"ENABLE Stage"}),(0,n.jsx)(s.th,{children:"How Abandonment Shows Up"})]})}),(0,n.jsxs)(s.tbody,{children:[(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/requirement-setting",children:["Set ",(0,n.jsx)(s.strong,{children:"Requirements"})," that Include Accessibility"]})}),(0,n.jsx)(s.td,{children:"Accessibility is dropped from the scope of future development priorities"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/content",children:["Create Accessible ",(0,n.jsx)(s.strong,{children:"Content"})]})}),(0,n.jsx)(s.td,{children:"Captions, alt text, or accessible formats are outdated or removed during migration"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/design",children:[(0,n.jsx)(s.strong,{children:"Design"})," Accessible Experiences"]})}),(0,n.jsx)(s.td,{children:"Visual refreshes disregard earlier inclusive patterns and there is no continuity testing"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/development",children:[(0,n.jsx)(s.strong,{children:"Develop"})," Accessible Implementations"]})}),(0,n.jsx)(s.td,{children:"Upgrades break accessibility implementations that once worked and no fallbacks are preserved"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/qa-testing",children:[(0,n.jsx)(s.strong,{children:"Test"})," for Accessibility"]})}),(0,n.jsx)(s.td,{children:"Regression testing excludes accessibility scenarios that were previously covered"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/triage",children:[(0,n.jsx)(s.strong,{children:"Triage"})," and Prioritize Accessibility Issues"]})}),(0,n.jsx)(s.td,{children:'Known accessibility bugs are downgraded, reclassified as "feature requests", or indefinitely deferred'})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/iteration",children:[(0,n.jsx)(s.strong,{children:"Iterate"})," to Address Shortcomings"]})}),(0,n.jsx)(s.td,{children:"Features regress across iterations without response or resolution"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/builder-side/stopgaps",children:["Create ",(0,n.jsx)(s.strong,{children:"Stopgaps"})]})}),(0,n.jsx)(s.td,{children:"Stopgaps are left in place permanently instead of remediating underlying issues"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/assistive-technologies",children:["Use ",(0,n.jsx)(s.strong,{children:"Assistive Technologies"})]})}),(0,n.jsx)(s.td,{children:"An update breaks screen-reader compatibility and is never addressed -- access is no longer possible for screen-reader users"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/third-party-tools",children:["Augment with ",(0,n.jsx)(s.strong,{children:"Third-Party Tools"})]})}),(0,n.jsx)(s.td,{children:"Critical fixes once provided by third-party scripts or extensions become unsupported or incompatible"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/system-settings",children:["Change ",(0,n.jsx)(s.strong,{children:"System Settings"})]})}),(0,n.jsx)(s.td,{children:"Platform updates override user configurations and accessible overrides are no longer respected"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/user-workarounds",children:["Create ",(0,n.jsx)(s.strong,{children:"Workarounds"})]})}),(0,n.jsx)(s.td,{children:"Workarounds that once enabled access become obsolete with no alternatives"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/human-help",children:["Use ",(0,n.jsx)(s.strong,{children:"Humans"})," for Assistance"]})}),(0,n.jsx)(s.td,{children:"Channels for human assistance are eliminated, leaving users without a fallback when automation fails"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/give-feedback",children:["Submit ",(0,n.jsx)(s.strong,{children:"Feedback"})," to Creators"]})}),(0,n.jsx)(s.td,{children:'Reports of regressions are acknowledged as bugs, but never fixed. They\'re eventually closed as "WONTFIX" without a satisfactory workaround.'})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/assert-rights",children:["Assert One's ",(0,n.jsx)(s.strong,{children:"Rights"})]})}),(0,n.jsx)(s.td,{children:"Legal protections that once ensured access are reversed or gutted. States preempt stronger local laws and sue to reverse federal laws. Courts narrow ADA interpretations (e.g., limiting the definition of \u201cpublic accommodation\u201d in digital spaces). Federal agencies drop enforcement. Access that was once won is now stripped away."})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/protest",children:["Stage a ",(0,n.jsx)(s.strong,{children:"Protest"})]})}),(0,n.jsx)(s.td,{children:"Protests are ignored or retaliated against, and no solutions are created -- the withdrawn access is never restored"})]}),(0,n.jsxs)(s.tr,{children:[(0,n.jsx)(s.td,{children:(0,n.jsxs)(s.a,{href:"/docs/navigator-side/switch-to-alternative",children:["Switch to an ",(0,n.jsx)(s.strong,{children:"Alternative"})]})}),(0,n.jsx)(s.td,{children:"The original tool becomes unusable -- updates halt, bugs accumulate, and compatibility breaks. However, no alternatives preserve the same function. What once enabled participation now prevents it."})]})]})]}),"\n",(0,n.jsx)(s.h2,{id:"how-it-disables",children:"How It Disables"}),"\n",(0,n.jsx)(s.p,{children:"Abandonment disables by revoking function -- breaking workflows, removing features, or severing access that people depend on. It turns previously accessible systems into barriers, often without warning."}),"\n",(0,n.jsxs)(s.ul,{children:["\n",(0,n.jsx)(s.li,{children:"It undermines reliability, making users hesitant to trust even well-designed tools."}),"\n",(0,n.jsx)(s.li,{children:"It interrupts autonomy, forcing users to re-learn, re-route, or re-seek support for once-simple tasks."}),"\n",(0,n.jsx)(s.li,{children:"It disorients: systems behave differently than before, but users receive no notice or support."}),"\n",(0,n.jsxs)(s.li,{children:["It erodes resilience: every act of ",(0,n.jsx)(s.a,{href:"/docs/navigator-side",children:"compensation"})," costs energy -- and when care disappears, that burden falls solely on the user."]}),"\n",(0,n.jsxs)(s.li,{children:["It displaces labor: instead of being sustained by ",(0,n.jsx)(s.a,{href:"/docs/builder-side",children:"builder-side interventions"}),", access must now be rebuilt from scratch -- by the people most harmed."]}),"\n"]}),"\n",(0,n.jsx)(s.p,{children:"Abandonment disables by removing bridges that once made participation possible."}),"\n",(0,n.jsx)(s.h2,{id:"why-it-matters",children:"Why It Matters"}),"\n",(0,n.jsx)(s.p,{children:"Abandonment gets into the body, into behavior, and into systems."}),"\n",(0,n.jsx)(s.p,{children:"Accessibility abandonment is not just a technical issue -- it's a social signal. It tells people with disabilities that they were never the priority, their inclusion was temporary, and their access was always conditional -- valued only when convenient."}),"\n",(0,n.jsxs)(s.p,{children:["Abandonment forces people with disabilities to ",(0,n.jsx)(s.a,{href:"/docs/navigator-side",children:"compensate"}),": to hack, adapt, or call for help, These are not choices -- they are survival strategies in the absence of care."]}),"\n",(0,n.jsxs)(s.p,{children:["Abandonment inflicts harm. In many ways, abandonment is more damaging than primordial neglect because it ",(0,n.jsx)(s.em,{children:"withdraws"})," something people have come to rely on. More than technical failure, it causes grief, disorientation, devastation, and fatigue. It fosters mistrust and teaches people to expect betrayal. Over time, some stop asking. Others stop showing up."]}),"\n",(0,n.jsx)(s.p,{children:"Abandonment costs more. Organizations that remove or regress accessibility often face increased support tickets, legal risk, reputational damage, and user churn. Fixing regressions post-release is more expensive than preserving access throughout. Rebuilding lost processes, retraining teams, restoring institutional memory, and re-earning trust takes more time, effort, and money than sustaining it in the first place."}),"\n",(0,n.jsxs)(s.p,{children:["Abandonment erodes autonomy. People who had built routines, jobs, and lives around accessible systems are suddenly forced to start over -- often without warning, support, or ",(0,n.jsx)(s.a,{href:"/docs/navigator-side/switch-to-alternative",children:"alternatives"}),". This loss isn't abstract: it can block someone from applying for a job, refilling a prescription, renewing a license, or booking transit."]}),"\n",(0,n.jsx)(s.p,{children:"Abandonment undermines public trust and safety. Accessible digital services enable access to healthcare, transportation, education, and disaster alerts. When access disappears, outcomes are harmed -- including increased hospitalization risk, preventable fines, missed deadlines, and loss of income."}),"\n",(0,n.jsx)(s.p,{children:"Abandonment undermines progress. Every hard-fought gain that is withdrawn must be fought for again. Hard-won access becomes fragile. When people see prior victories undone, they're less likely to trust future promises. The message to disabled people is clear: nothing stays accessible unless you keep demanding it."}),"\n",(0,n.jsx)(s.p,{children:"Abandonment turns assets into liabilities. Once an organization begins to withdraw from accessibility, things that would strengthen the work start to look inconvenient, burdensome, or even threatening. Partnership becomes obligation. Momentum becomes friction. Community becomes contradiction. Maintaining them would contradict the decision to walk away. Abandonment requires more than stepping back; it demands discarding the assets that would keep the work alive so the retreat can continue."}),"\n",(0,n.jsx)(s.p,{children:'Abandonment collapses pathways. When an organization withdraws from accessibility, future possibilities that would be celebrated -- outreach, visibility, recruitment, collaboration -- become distractions. Pursuing them would imply continuity that leadership has already disavowed. What should have been momentum becomes something that cannot be acted on. Abandonment doesn\u2019t just drop what is held; it passes on what was about to come into grasp. Timely opportunities become "too late."'}),"\n",(0,n.jsx)(s.p,{children:"Abandonment reactivates trauma. The fear of abandonment is a well-documented trauma response -- one that many disabled people already carry from medical neglect, social exclusion, or institutional betrayal. Inaccessibility deepens that wound. Each broken login or vanished caption confirms what experience has already taught: inclusion is fleeting, and care can disappear without warning. This isn't overreaction -- it's recognition."}),"\n",(0,n.jsx)(s.p,{children:"Abandonment rewires behavior. After enough betrayals, people learn not to reach. Some avoid updates. Some stop filing tickets. Some stop expecting accessibility at all. What looks like withdrawal is often self-protection -- a way to reduce the pain of being let down again."}),"\n",(0,n.jsx)(s.h2,{id:"real-world-examples",children:"Real-World Examples"}),"\n",(0,n.jsxs)(s.admonition,{title:"In the news",type:"info",children:[(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.facebook.com/photo/?fbid=1247046553944472",children:"Rubio Deletes Calibri As the State Department's Official Typeface"})," (December 10, 2025) ",(0,n.jsx)("br",{}),"\n-- Haiyn Jiang for The New York Times (",(0,n.jsx)(s.a,{href:"https://www.nytimes.com/2025/12/09/us/politics/rubio-state-department-font.html?",children:"Publisher's version"}),")"]}),(0,n.jsxs)(s.blockquote,{children:["\n",(0,n.jsx)(s.p,{children:"Secretary of State Marco Rubio halted the State Department\u2019s official use of the typeface Calibri, calling the Biden-era move \u201cwasteful,\u201d and ordered the return of Times New Roman as part of a push to stamp out diversity efforts. In 2023, Secretary of State Antony Blinken ordered the typeface change to Calibri to improve accessibility for readers with disabilities, such as low vision and dyslexia, and people who use assistive technologies, such as screen readers."}),"\n"]})]}),"\n",(0,n.jsxs)(s.ul,{children:["\n",(0,n.jsx)(s.li,{children:"A government site that once had a plain-text alternative silently removes it during rebranding."}),"\n",(0,n.jsx)(s.li,{children:"A screen reader-friendly layout is quietly replaced with a visual refresh that ignores prior usability testing."}),"\n",(0,n.jsx)(s.li,{children:"A formerly accessible transit app no longer works with screen readers after a \u201cmodernization\u201d push."}),"\n",(0,n.jsx)(s.li,{children:"A once-accessible booking form becomes unusable after a JavaScript framework upgrade."}),"\n",(0,n.jsx)(s.li,{children:"A CMS upgrade breaks keyboard navigation. It stays broken for months."}),"\n",(0,n.jsx)(s.li,{children:"A streaming platform removes captions from archived content after redesign."}),"\n",(0,n.jsx)(s.li,{children:"A redesign breaks alt-text rendering in a journal site. No one notices until researchers file complaints months later."}),"\n",(0,n.jsx)(s.li,{children:"A browser extension that fixed a longstanding barrier becomes incompatible with a new version. No alternative is offered."}),"\n"]}),"\n",(0,n.jsx)(s.h2,{id:"what-care-sounds-like",children:"What Care Sounds Like"}),"\n",(0,n.jsxs)(s.blockquote,{children:["\n",(0,n.jsxs)(s.p,{children:["\u201cWe've budgeted for long-term accessibility -- not just launch.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cThis redesign won't ship until we confirm it doesn't break screen reader workflows.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cWe're tracking regressions and restoring anything that was lost.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cWe included disabled testers from the start -- and after each update.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cWe know this feature used to work, and we're sorry it no longer does. We're prioritizing its return.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cWe're building a regression suite that includes accessibility.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cAccessibility isn't a feature. It's our responsibility.\u201d"]}),"\n"]}),"\n",(0,n.jsx)(s.h2,{id:"what-neglect-sounds-like",children:"What Neglect Sounds Like"}),"\n",(0,n.jsxs)(s.blockquote,{children:["\n",(0,n.jsxs)(s.p,{children:["\u201cWe had to move fast.\u201d",(0,n.jsx)(s.br,{}),"\n",'"We don\'t have disabled users."',(0,n.jsx)(s.br,{}),"\n","\u201cAccessibility wasn't in the new scope.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cIt broke during the upgrade -- we'll look at it later.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cNobody complained.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cIt's no longer a priority.\u201d",(0,n.jsx)(s.br,{}),"\n","\u201cIt's in the backlog.\u201d"]}),"\n"]}),"\n",(0,n.jsx)(s.hr,{}),"\n",(0,n.jsx)(s.p,{children:"Accessibility lost is still a form of inaccessibility. ENABLE names this tendency so we don't normalize it."}),"\n",(0,n.jsx)(s.hr,{}),"\n",(0,n.jsxs)(s.blockquote,{children:["\n",(0,n.jsx)(s.p,{children:"Have you roped any conclusions from the riddles that you found?\n-- Lissie"}),"\n"]}),"\n",(0,n.jsx)(s.hr,{}),"\n",(0,n.jsx)(s.p,{children:(0,n.jsx)(s.em,{children:"Edited by Lawrence Weru S.M. (Harvard)"})})]})}function h(e={}){const{wrapper:s}={...(0,a.R)(),...e.components};return s?(0,n.jsx)(s,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},8453:(e,s,t)=>{t.d(s,{R:()=>r,x:()=>o});var i=t(6540);const n={},a=i.createContext(n);function r(e){const s=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),i.createElement(a.Provider,{value:s},e.children)}}}]);